      if (h.length) out.hits.push([lang, n, h]); } }
  api.setLang('ja', true); api.goto(0, {instant: true, silent: true});
  if (out.hits.length) throw new Error('scan: ' + JSON.stringify(out)); return JSON.stringify(out); })()
